import{_ as o,o as t,c as a,a4 as r}from"./chunks/framework.DpieW3qv.js";const m=JSON.parse('{"title":"Developer Guide","description":"","frontmatter":{"title":"Developer Guide"},"headers":[],"relativePath":"guides/developer-guide.md","filePath":"guides/developer-guide.md","lastUpdated":null}'),n={name:"guides/developer-guide.md"};function d(c,e,i,s,l,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="developer-guide" tabindex="-1">Developer Guide <a class="header-anchor" href="#developer-guide" aria-label="Permalink to &quot;Developer Guide&quot;">​</a></h1><p>How the CLI is built and how to add or change behavior. For architecture detail, see <a href="/ocapi-docs.github.io/reference/architecture.html">Architecture</a>.</p><hr><h2 id="architecture-overview" tabindex="-1">Architecture overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture overview&quot;">​</a></h2><p>The app uses <strong>Clean Architecture</strong>-style layers:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Location</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>CLI</strong></td><td><code>src/cli/</code></td><td>Entry point, command routing, flags, output</td></tr><tr><td><strong>Application</strong></td><td><code>src/application/usecases/</code></td><td>Workflows (Excel, Dev, SFCC, Reporting, Health)</td></tr><tr><td><strong>Domain</strong></td><td><code>src/domain/</code></td><td>Entities (Campaign, ContentAsset, SlotConfiguration), validation</td></tr><tr><td><strong>Infrastructure</strong></td><td><code>src/infrastructure/</code></td><td>File system, OCAPI client, parsing, rendering, registry</td></tr></tbody></table><p>The CLI is thin: it parses arguments, builds a <code>BrandContext</code>, and delegates to use cases.</p><hr><h2 id="cli-entrypoint" tabindex="-1">CLI entrypoint <a class="header-anchor" href="#cli-entrypoint" aria-label="Permalink to &quot;CLI entrypoint&quot;">​</a></h2><ul><li><strong>File:</strong> <code>src/cli/index.js</code></li><li><strong>Responsibilities:</strong> Parse <code>process.argv</code>, resolve brand (from config or <code>BRAND=</code>), parse flags with <code>parseFlags()</code> and <code>buildOptions()</code>, create <code>BrandContext</code>, dispatch to the right handler in <code>src/cli/commands/</code>.</li><li><strong>Makefile as source of truth:</strong> Commands are invoked via the Makefile (e.g. <code>make build</code> runs <code>node src/cli/index.js refresh ...</code>). The Makefile is the canonical interface for controlling the application; see <a href="/ocapi-docs.github.io/reference/commands.html#makefile-as-source-of-truth">Commands Reference</a> for the Make variable → CLI flag table. The binary <code>sfcc-cli</code> (from <code>package.json</code> bin) runs the same entrypoint.</li></ul><hr><h2 id="command-structure" tabindex="-1">Command structure <a class="header-anchor" href="#command-structure" aria-label="Permalink to &quot;Command structure&quot;">​</a></h2><ul><li><strong>Handlers:</strong> One file per command under <code>src/cli/commands/</code> (e.g. <code>handleRefresh.js</code>, <code>handleSync.js</code>).</li><li><strong>Pattern:</strong> Each handler receives <code>(brand, target, options, ...)</code>. It uses <code>resolveRefreshForCommand</code> or similar when it needs a single refresh, then calls a use case on <code>brand.usecases.*</code>.</li><li><strong>Adding a command:</strong> See <a href="#adding-a-new-command">Adding a new command</a> below.</li></ul><hr><h2 id="adding-a-new-command" tabindex="-1">Adding a new command <a class="header-anchor" href="#adding-a-new-command" aria-label="Permalink to &quot;Adding a new command&quot;">​</a></h2><ol><li><strong>Register in the router:</strong> In <code>src/cli/index.js</code>, add the command to <code>COMMAND_MAP</code> and add a <code>case</code> in <code>runCommand()</code> that calls your new handler.</li><li><strong>Create the handler:</strong> Add <code>src/cli/commands/handleMyCommand.js</code>. Resolve brand/target/options (use <code>resolveRefreshForCommand</code> if the command needs a refresh), then call the appropriate use case.</li><li><strong>Use case (if needed):</strong> If the command needs new business logic, add a use case in the right workflow file under <code>src/application/usecases/</code>, and expose it via <code>BrandContext</code>.</li><li><strong>Make target (optional):</strong> In the Makefile, add a target that runs <code>$(CLI) myCommand $(BRAND) ...</code> with the right flags.</li><li><strong>Document:</strong> Add <code>docs/cli/my-command.md</code> and link it from <a href="/ocapi-docs.github.io/cli/">Commands</a> and <a href="/ocapi-docs.github.io/reference/commands.html">reference/commands</a>.</li></ol><hr><h2 id="brandcontext-and-dependency-injection" tabindex="-1">BrandContext and dependency injection <a class="header-anchor" href="#brandcontext-and-dependency-injection" aria-label="Permalink to &quot;BrandContext and dependency injection&quot;">​</a></h2><ul><li><strong>BrandContext</strong> (<code>src/application/context/BrandContext.js</code>) is the composition root: it holds the brand id, file store, SFCC config, and <strong>usecases</strong> (Excel, Dev, Sfcc, Reporting, Health).</li><li>Handlers receive a <code>BrandContext</code> instance; they don&#39;t construct use cases themselves. This keeps the CLI testable (you can pass a mock or test brand).</li><li>Config is loaded from <code>app.config</code>, <code>slots.config</code>, <code>sfcc.config</code>, and user config (<code>.ocapi-config.json</code>, <code>.env</code>).</li></ul><hr><h2 id="testing-strategy" tabindex="-1">Testing strategy <a class="header-anchor" href="#testing-strategy" aria-label="Permalink to &quot;Testing strategy&quot;">​</a></h2><ul><li><strong>Unit tests:</strong> Under <code>tests/</code> — config, domain, services, usecases, utils. Vitest; include pattern <code>tests/**/*.test.js</code>.</li><li><strong>CLI tests:</strong> Under <code>tests/cli/</code> — command routing, guards, prompts. Use mocks for file system and OCAPI where needed.</li><li><strong>Integration:</strong> <code>tests/integration/workflow.test.js</code> and similar for full flows.</li><li><strong>Test commands (Makefile is source of truth):</strong> See <a href="/ocapi-docs.github.io/reference/commands.html#test-commands">Commands Reference</a>. Summary: <code>make test</code> (run all), <code>make test-watch</code> (watch mode), <code>make test-coverage</code> (coverage report), <code>make test-brands</code> (E2E both brands), <code>make check</code> (lint + tests for CI).</li></ul><hr><h2 id="code-conventions" tabindex="-1">Code conventions <a class="header-anchor" href="#code-conventions" aria-label="Permalink to &quot;Code conventions&quot;">​</a></h2><ul><li><strong>Lint:</strong> ESLint (see <code>.eslintrc.json</code>). Run <code>npm run lint</code> or <code>make check</code>.</li><li><strong>Format:</strong> Prettier (see <code>.prettierrc</code>). Run <code>npm run format</code>.</li><li><strong>JSDoc:</strong> Used for public APIs and for generating <a href="/ocapi-docs.github.io/reference/api/">API Reference</a>. Run <code>make docs-build</code> to regenerate API docs.</li></ul><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/ocapi-docs.github.io/reference/architecture.html">Architecture</a> — Full system design and layer details</li><li><a href="/ocapi-docs.github.io/reference/api/">API Reference</a> — Generated from JSDoc</li><li><a href="/ocapi-docs.github.io/operations/runbook.html">Runbook</a> — Release checklist and operations</li></ul>',28)])])}const g=o(n,[["render",d]]);export{m as __pageData,g as default};
